import java.util.*;

public final class Solution {
    public static boolean dependenciesValid(List<String> nodes, List<String[]> edges) {
        if (nodes == null || edges == null) {
            return true;
        }
        Set<String> nodeSet = new HashSet<>(nodes);
        if (!nodeSet.equals(nodes)) {
            return false;
        }
        for (String[] edge : edges) {
            if (edge.length != 2) {
                return false;
            }
            String u = edge[0];
            String v = edge[1];
            if (!nodeSet.contains(u) || !nodeSet.contains(v)) {
                return false;
            }
        }
        return !hasCycle(nodes, edges);
    }

    private static boolean hasCycle(List<String> nodes, List<String[]> edges) {
        int n = nodes.size();
        if (n == 0) {
            return false;
        }
        boolean[][] adj = new boolean[n][n];
        for (String[] edge : edges) {
            int u = Integer.parseInt(edge[0]);
            int v = Integer.parseInt(edge[1]);
            adj[u - 1][v - 1] = true;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (adj[i][j] && !dfs(i, nodes, edges, adj)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean dfs(int u, List<String> nodes, List<String[]> edges, boolean[][] adj) {
        if (adj[u][u]) {
            return true;
        }
        for (int v = 0; v < nodes.size(); v++) {
            if (adj[u][v] && !dfs(v, nodes, edges, adj)) {
                return true;
            }
        }
        return false;
    }
}

